import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getReport } from "../handlers/getReport";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpaceReportEntityType } from "../types/SpaceReportEntityType";

type Data = Awaited<ReturnType<typeof getReport>>;

export function useGetReport(
  spacePk: SpacePartition,
  reportId: SpaceReportEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getReport", spacePk, reportId],
    queryFn: () => getReport(spacePk, reportId),
    ...options,
  });
}
